INTERACTION_ROWS = [('fluoxetine', 'aripiprazole', 'major', 'PK', 'Fluoxetine is a strong CYP2D6 inhibitor; aripiprazole is a major CYP2D6 substrate (fm = 0.35). Co-administration increases aripiprazole AUC by ~112%.', 'Markedly elevated aripiprazole levels leading to increased risk of akathisia, sedation, QTc prolongation, and EPS.', 'Reduce aripiprazole dose by 50% when combined with strong CYP2D6 inhibitors. Monitor for EPS and akathisia.', 'strong'), ('fluvoxamine', 'clozapine', 'critical', 'PK', 'Fluvoxamine is a strong CYP1A2 inhibitor (Ki = 50 nM); clozapine is 70% metabolized by CYP1A2. Co-administration increases clozapine levels 5-10 fold.', 'POTENTIALLY FATAL: clozapine toxicity — seizures, myocarditis, respiratory depression, cardiovascular collapse.', 'Avoid combination if possible. If used, reduce clozapine dose by 66-75% and monitor levels closely (target 350-600 ng/mL). Slow titration mandatory.', 'strong'), ('fluvoxamine', 'olanzapine', 'moderate', 'PK', 'Fluvoxamine strongly inhibits CYP1A2; olanzapine is 60% metabolized by CYP1A2. AUC increase ~52-108%.', 'Elevated olanzapine levels increasing risk of sedation, metabolic effects, and EPS.', 'Consider olanzapine dose reduction by 50% and monitor TDM levels. Watch for excessive sedation.', 'strong'), ('carbamazepine', 'quetiapine', 'major', 'PK', 'Carbamazepine is a strong CYP3A4 inducer; quetiapine is 80% metabolized by CYP3A4. Quetiapine levels decrease by ~80%.', 'Sub-therapeutic quetiapine levels leading to treatment failure (psychotic relapse, mood destabilization).', 'Avoid combination. If unavoidable, quetiapine dose may need to be increased up to 5-fold with close monitoring. Consider alternative mood stabilizer.', 'strong'), ('carbamazepine', 'lamotrigine', 'major', 'PK', 'Carbamazepine induces UGT1A4, the primary metabolic pathway for lamotrigine. Lamotrigine clearance increases ~100%, halving levels.', 'Sub-therapeutic lamotrigine levels and increased risk of breakthrough seizures or mood episodes.', 'Lamotrigine dose typically needs to be doubled (target 300-400 mg/day vs 100-200 mg/day monotherapy). Follow lamotrigine-specific titration schedule for enzyme-inducing AEDs.', 'strong'), ('valproic acid', 'lamotrigine', 'major', 'PK', 'Valproic acid inhibits UGT1A4 glucuronidation of lamotrigine, approximately doubling lamotrigine half-life (from 25 h to ~60 h) and AUC.', 'Markedly elevated lamotrigine levels increasing risk of Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN), especially during rapid titration.', 'Use VPA-specific lamotrigine titration schedule: start 25 mg every other day, increase by 25 mg/day every 2 weeks. Target lamotrigine dose typically 100-200 mg/day (half of monotherapy dose).', 'strong'), ('citalopram', 'ziprasidone', 'major', 'PD', 'Both agents independently prolong the QTc interval. Additive risk of Torsades de Pointes.', 'Increased risk of QTc prolongation, ventricular arrhythmias, and sudden cardiac death.', 'Avoid combination. If clinically necessary, obtain baseline ECG, monitor QTc closely, maintain electrolytes (K+, Mg2+). Consider escitalopram (lower QTc risk) or alternative antipsychotic.', 'moderate'), ('escitalopram', 'ziprasidone', 'major', 'PD', 'Both agents prolong QTc interval. Additive risk though lower than citalopram + ziprasidone.', 'Increased risk of QTc prolongation and ventricular arrhythmias.', 'Use with caution. Baseline and periodic ECG monitoring. Correct electrolyte abnormalities before initiating.', 'moderate'), ('haloperidol', 'methadone', 'major', 'PD', 'Both agents prolong QTc interval. Methadone has dose-dependent QTc prolongation; haloperidol prolongs QTc especially at higher doses or via IV route.', 'High risk of QTc prolongation, Torsades de Pointes, and sudden cardiac death.', 'Avoid combination if possible. If required, obtain baseline ECG, monitor QTc at each dose change, keep QTc < 500 ms. Consider aripiprazole as alternative antipsychotic.', 'strong'), ('phenelzine', 'fluoxetine', 'critical', 'PD', 'Phenelzine (irreversible MAOI) combined with fluoxetine (potent serotonin reuptake inhibitor) causes unopposed serotonin accumulation in CNS synapses.', 'Life-threatening serotonin syndrome: hyperthermia, rigidity, myoclonus, autonomic instability, altered mental status, coma, death.', 'ABSOLUTELY CONTRAINDICATED. Minimum 5-week washout after stopping fluoxetine before starting MAOI (due to long t1/2 of norfluoxetine). Minimum 2-week washout after stopping MAOI before starting fluoxetine.', 'strong'), ('phenelzine', 'sertraline', 'critical', 'PD', 'Irreversible MAOI combined with potent SSRI causes massive serotonergic excess.', 'Life-threatening serotonin syndrome: hyperthermia, rigidity, myoclonus, autonomic instability, coma, death.', 'ABSOLUTELY CONTRAINDICATED. Minimum 2-week washout in both directions (MAOI to SSRI and SSRI to MAOI).', 'strong'), ('tranylcypromine', 'venlafaxine', 'critical', 'PD', 'Irreversible MAOI combined with SNRI causes dangerous serotonergic excess.', 'Life-threatening serotonin syndrome with potentially fatal hyperthermia and cardiovascular collapse.', 'ABSOLUTELY CONTRAINDICATED. Minimum 2-week washout after stopping MAOI; minimum 1-week washout after stopping venlafaxine before starting MAOI.', 'strong'), ('paroxetine', 'risperidone', 'major', 'PK', 'Paroxetine is a strong CYP2D6 inhibitor; risperidone is 60% metabolized by CYP2D6. Risperidone AUC increases ~45-75%.', 'Elevated risperidone levels with increased EPS and prolactin elevation risk.', 'Reduce risperidone dose or monitor levels closely. Consider alternative SSRI with less CYP2D6 inhibition.', 'strong'), ('fluoxetine', 'clomipramine', 'major', 'PK', 'Fluoxetine strongly inhibits CYP2D6; clomipramine is partially metabolized by CYP2D6. Plus additive serotonergic effects.', 'Elevated clomipramine levels and additive serotonin toxicity risk. Seizure risk increased.', 'Avoid combination. If used, reduce clomipramine dose substantially and monitor TDM. Watch for serotonin syndrome signs.', 'strong'), ('carbamazepine', 'aripiprazole', 'major', 'PK', 'Carbamazepine is a strong CYP3A4 inducer; aripiprazole is 65% metabolized by CYP3A4. Aripiprazole AUC decreases ~70%.', 'Sub-therapeutic aripiprazole levels leading to loss of efficacy.', 'Double aripiprazole dose (to 20-30 mg/day) when used with strong CYP3A4 inducers per FDA labeling.', 'strong'), ('fluoxetine', 'tramadol', 'major', 'PK+PD', 'Fluoxetine inhibits CYP2D6, reducing conversion of tramadol to active metabolite (reduced analgesia) while increasing parent compound (increased serotonergic activity). Additive serotonergic effects.', 'Dual risk: reduced analgesic efficacy AND increased serotonin syndrome risk.', 'Avoid combination. Consider alternative analgesic without serotonergic properties.', 'moderate'), ('sertraline', 'tramadol', 'major', 'PD', 'Additive serotonergic activity: sertraline (SRI) plus tramadol (weak SRI and mu-agonist).', 'Increased risk of serotonin syndrome, seizures.', 'Avoid if possible. If used, start at low doses, monitor for serotonin syndrome symptoms. Educate patient.', 'moderate'), ('citalopram', 'methadone', 'major', 'PD', 'Both agents prolong QTc interval. Citalopram has dose-dependent QTc effect; methadone QTc prolongation increases above 100 mg/day.', 'Additive QTc prolongation risk. Torsades de Pointes.', 'Avoid high-dose citalopram (>20 mg) with methadone. ECG monitoring at baseline and with dose changes. Consider alternative SSRI.', 'moderate'), ('clozapine', 'carbamazepine', 'critical', 'PD', 'Both agents independently carry risk of bone marrow suppression. Carbamazepine also induces CYP3A4 (minor clozapine pathway) and may reduce clozapine levels.', 'Additive risk of agranulocytosis/neutropenia. Sub-therapeutic clozapine levels from CYP induction.', 'CONTRAINDICATED per clozapine REMS. Do not combine.', 'strong'), ('phenelzine', 'tramadol', 'critical', 'PD', 'MAOI plus serotonergic opioid (SNRI mechanism).', 'Life-threatening serotonin syndrome.', 'ABSOLUTELY CONTRAINDICATED.', 'strong'), ('lithium', 'carbamazepine', 'moderate', 'PD', 'Pharmacodynamic interaction: additive neurotoxic effects without significant PK interaction. Carbamazepine may reduce renal lithium clearance in some patients.', 'Increased risk of neurotoxicity (ataxia, tremor, nystagmus, confusion) even at therapeutic levels of each drug.', 'Monitor for neurotoxicity signs. Monitor lithium levels. Use with caution; combination can be clinically useful.', 'moderate'), ('bupropion', 'paroxetine', 'moderate', 'PK', 'Both are CYP2D6 inhibitors. Paroxetine is also a CYP2D6 substrate. Bupropion may increase paroxetine levels.', 'Elevated paroxetine levels; increased anticholinergic and serotonergic side effects.', 'Monitor for paroxetine side effects. Consider alternative SSRI with less CYP2D6 dependence.', 'moderate'), ('duloxetine', 'tramadol', 'major', 'PD', 'Additive serotonergic activity: duloxetine (SNRI) plus tramadol (weak SNRI + mu-agonist). Duloxetine also inhibits CYP2D6 (tramadol activation).', 'Serotonin syndrome risk plus altered tramadol metabolism.', 'Avoid if possible. If used, monitor closely for serotonin syndrome.', 'moderate'), ('carbamazepine', 'lurasidone', 'critical', 'PK', 'Carbamazepine is a strong CYP3A4 inducer; lurasidone is 85% metabolized by CYP3A4.', 'Dramatically reduced lurasidone levels; loss of antipsychotic efficacy.', 'CONTRAINDICATED per lurasidone FDA labeling. Do not combine.', 'strong'), ('tranylcypromine', 'sertraline', 'critical', 'PD', 'Irreversible MAOI combined with potent SSRI.', 'Life-threatening serotonin syndrome.', 'ABSOLUTELY CONTRAINDICATED. 2-week washout required in both directions.', 'strong'), ('phenelzine', 'clomipramine', 'critical', 'PD', 'MAOI plus most serotonergic TCA. Extreme serotonergic excess.', 'Life-threatening serotonin syndrome. Deaths reported.', 'ABSOLUTELY CONTRAINDICATED. 2-week washout required.', 'strong'), ('carbamazepine', 'alprazolam', 'moderate', 'PK', 'Carbamazepine induces CYP3A4; alprazolam is 80% CYP3A4 substrate. Alprazolam levels may decrease substantially.', 'Reduced alprazolam efficacy; potential withdrawal if levels drop significantly.', 'Consider lorazepam (glucuronidation, no CYP dependence) as alternative. If using alprazolam, may need dose increase with monitoring.', 'moderate'), ('fluvoxamine', 'alprazolam', 'moderate', 'PK', 'Fluvoxamine moderately inhibits CYP3A4; alprazolam is 80% CYP3A4 substrate. Alprazolam AUC increases ~100%.', 'Excessive sedation, respiratory depression, psychomotor impairment.', 'Reduce alprazolam dose by 50%. Consider lorazepam as alternative.', 'strong'), ('carbamazepine', 'haloperidol', 'moderate', 'PK', 'Carbamazepine induces CYP3A4; haloperidol is partially (50%) metabolized by CYP3A4.', 'Reduced haloperidol levels (up to 60% decrease) leading to loss of antipsychotic efficacy.', 'Monitor haloperidol levels and clinical response. May need significant dose increase.', 'moderate'), ('fluoxetine', 'methadone', 'major', 'PK+PD', 'Fluoxetine inhibits CYP2D6 (minor methadone pathway) and both carry QTc risk potential. May increase methadone levels modestly.', 'Increased methadone levels and additive QTc prolongation risk.', 'Monitor QTc. Consider sertraline as lower-risk SSRI alternative with methadone.', 'moderate'), ('valproic acid', 'carbamazepine', 'major', 'PK+PD', 'Carbamazepine induces valproic acid metabolism (reducing VPA levels by ~25-50%); simultaneously, valproic acid inhibits epoxide hydrolase, causing accumulation of carbamazepine-10,11-epoxide (toxic metabolite).', 'Sub-therapeutic VPA levels AND toxic carbamazepine epoxide accumulation — neurotoxicity, hepatotoxicity.', 'Monitor both drug levels including carbamazepine epoxide levels. Consider alternative mood stabilizer combination.', 'strong'), ('tranylcypromine', 'fluoxetine', 'critical', 'PD', 'Tranylcypromine (irreversible MAOI) combined with fluoxetine (potent serotonin reuptake inhibitor) causes unopposed serotonin accumulation in CNS synapses.', 'Life-threatening serotonin syndrome: hyperthermia, rigidity, myoclonus, autonomic instability, altered mental status, coma, death.', 'ABSOLUTELY CONTRAINDICATED. Minimum 5-week washout after stopping fluoxetine before starting MAOI (due to long t1/2 of norfluoxetine). Minimum 2-week washout after stopping MAOI before starting fluoxetine.', 'strong'), ('phenelzine', 'venlafaxine', 'critical', 'PD', 'Irreversible MAOI combined with SNRI causes dangerous serotonergic excess.', 'Life-threatening serotonin syndrome with potentially fatal hyperthermia and cardiovascular collapse.', 'ABSOLUTELY CONTRAINDICATED. Minimum 2-week washout after stopping MAOI; minimum 1-week washout after stopping venlafaxine before starting MAOI.', 'strong'), ('tranylcypromine', 'duloxetine', 'critical', 'PD', 'Irreversible MAOI combined with SNRI causes dangerous serotonergic excess.', 'Life-threatening serotonin syndrome with potentially fatal hyperthermia and cardiovascular collapse.', 'ABSOLUTELY CONTRAINDICATED. Minimum 2-week washout after stopping MAOI; minimum 5 half-lives washout after stopping duloxetine before starting MAOI.', 'strong'), ('phenelzine', 'duloxetine', 'critical', 'PD', 'Irreversible MAOI combined with SNRI causes dangerous serotonergic excess.', 'Life-threatening serotonin syndrome with potentially fatal hyperthermia and cardiovascular collapse.', 'ABSOLUTELY CONTRAINDICATED. Minimum 2-week washout after stopping MAOI; minimum 5 half-lives washout after stopping duloxetine before starting MAOI.', 'strong'), ('phenelzine', 'paroxetine', 'critical', 'PD', 'Irreversible MAOI combined with potent SSRI causes massive serotonergic excess.', 'Life-threatening serotonin syndrome: hyperthermia, rigidity, myoclonus, autonomic instability, coma, death.', 'ABSOLUTELY CONTRAINDICATED. 2-week washout required in both directions (MAOI to SSRI and SSRI to MAOI).', 'strong'), ('tranylcypromine', 'paroxetine', 'critical', 'PD', 'Irreversible MAOI combined with potent SSRI causes massive serotonergic excess.', 'Life-threatening serotonin syndrome: hyperthermia, rigidity, myoclonus, autonomic instability, coma, death.', 'ABSOLUTELY CONTRAINDICATED. 2-week washout required in both directions (MAOI to SSRI and SSRI to MAOI).', 'strong'), ('paroxetine', 'aripiprazole', 'major', 'PK', 'Paroxetine is a strong CYP2D6 inhibitor; aripiprazole is a CYP2D6 substrate (fm = 0.35). Similar to fluoxetine + aripiprazole interaction.', 'Elevated aripiprazole levels; increased EPS and akathisia risk.', 'Reduce aripiprazole dose by 50% per FDA labeling.', 'strong'), ('bupropion', 'aripiprazole', 'moderate', 'PK', 'Bupropion is a moderate CYP2D6 inhibitor (Ki ~500 nM); aripiprazole is a CYP2D6 substrate.', 'Modest increase in aripiprazole levels (~30-40%).', 'Monitor for akathisia; aripiprazole dose reduction may be needed.', 'moderate')]
SCENARIO_ROWS = [{'name': 'SSRI-to-SNRI Cross-Taper with Aripiprazole Augmentation', 'description': "A 34-year-old woman with MDD has been on fluoxetine 40 mg/day + aripiprazole 10 mg/day for 8 weeks with partial response. The clinician decides to cross-taper from fluoxetine to venlafaxine XR. Key concern: fluoxetine's long half-life (parent + norfluoxetine) means CYP2D6 inhibition persists for 5-6 weeks after discontinuation, affecting aripiprazole metabolism throughout the transition. Additionally, premature venlafaxine initiation while fluoxetine levels remain significant creates serotonin toxicity risk.", 'medications': ['fluoxetine', 'aripiprazole', 'venlafaxine'], 'dose_events': [{'medication': 'fluoxetine', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 40.0, 'frequency': 'once daily'}, {'medication': 'aripiprazole', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 10.0, 'frequency': 'once daily'}, {'medication': 'fluoxetine', 'event_type': 'dose_change', 'day': 1, 'dose_mg': 20.0, 'frequency': 'once daily'}, {'medication': 'fluoxetine', 'event_type': 'stop', 'day': 14, 'dose_mg': 0.0, 'frequency': 'once daily'}, {'medication': 'venlafaxine', 'event_type': 'start', 'day': 21, 'dose_mg': 37.5, 'frequency': 'once daily'}, {'medication': 'venlafaxine', 'event_type': 'dose_change', 'day': 28, 'dose_mg': 75.0, 'frequency': 'once daily'}, {'medication': 'venlafaxine', 'event_type': 'dose_change', 'day': 42, 'dose_mg': 150.0, 'frequency': 'once daily'}]}, {'name': 'Clozapine and Smoking Cessation (CYP1A2 De-induction)', 'description': 'A 45-year-old man with treatment-resistant schizophrenia, stable on clozapine 400 mg/day (levels 420 ng/mL) for 2 years. He smokes 20 cigarettes/day, which induces CYP1A2 and keeps clozapine clearance elevated. He is admitted to an inpatient unit where smoking is prohibited. Within 2-3 days of smoking cessation, CYP1A2 de-induces and clozapine levels can rise 50-70%, potentially reaching toxic range (>1000 ng/mL). This scenario simulates the dangerous rise in clozapine concentrations and the need for proactive dose reduction.', 'medications': ['clozapine'], 'dose_events': [{'medication': 'clozapine', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 400.0, 'frequency': 'twice daily'}, {'medication': 'clozapine', 'event_type': 'dose_change', 'day': 3, 'dose_mg': 300.0, 'frequency': 'twice daily'}, {'medication': 'clozapine', 'event_type': 'dose_change', 'day': 7, 'dose_mg': 250.0, 'frequency': 'twice daily'}]}, {'name': 'Lamotrigine + Valproic Acid Titration (SJS Risk Management)', 'description': "A 28-year-old woman with bipolar II disorder is stable on valproic acid 1000 mg/day (level 80 ug/mL). The clinician wants to add lamotrigine for depressive episodes. Valproic acid inhibits UGT1A4, doubling lamotrigine's half-life. The FDA-mandated VPA-specific titration schedule requires starting at 25 mg every other day and increasing very slowly to reduce SJS risk. This scenario models the PK interaction and optimal titration timing.", 'medications': ['valproic acid', 'lamotrigine'], 'dose_events': [{'medication': 'valproic acid', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 1000.0, 'frequency': 'twice daily'}, {'medication': 'lamotrigine', 'event_type': 'start', 'day': 1, 'dose_mg': 25.0, 'frequency': 'every other day'}, {'medication': 'lamotrigine', 'event_type': 'dose_change', 'day': 15, 'dose_mg': 25.0, 'frequency': 'once daily'}, {'medication': 'lamotrigine', 'event_type': 'dose_change', 'day': 29, 'dose_mg': 50.0, 'frequency': 'once daily'}, {'medication': 'lamotrigine', 'event_type': 'dose_change', 'day': 43, 'dose_mg': 100.0, 'frequency': 'once daily'}]}, {'name': 'CYP2D6 Poor Metabolizer on Risperidone', 'description': "A 22-year-old man with first-episode psychosis is started on risperidone 2 mg/day. He is a CYP2D6 poor metabolizer (PM), meaning he cannot effectively convert risperidone to paliperidone. This results in elevated parent risperidone levels (~2-3x normal) with reduced paliperidone formation. Clinical consequences include excessive D2 blockade, severe EPS, and marked prolactin elevation despite a 'standard' dose. The simulation compares PK curves in a normal metabolizer vs. CYP2D6 PM.", 'medications': ['risperidone'], 'dose_events': [{'medication': 'risperidone', 'event_type': 'start', 'day': 1, 'dose_mg': 1.0, 'frequency': 'once daily'}, {'medication': 'risperidone', 'event_type': 'dose_change', 'day': 4, 'dose_mg': 2.0, 'frequency': 'once daily'}, {'medication': 'risperidone', 'event_type': 'dose_change', 'day': 8, 'dose_mg': 3.0, 'frequency': 'once daily'}]}, {'name': 'Polypharmacy Cascade — Treatment-Resistant Depression', 'description': 'A 55-year-old man with treatment-resistant depression, generalized anxiety, and chronic pain is on: sertraline 200 mg/day (depression), aripiprazole 5 mg augmentation, trazodone 100 mg at bedtime (insomnia), gabapentin 900 mg/day (anxiety/pain), and tramadol 200 mg/day (pain). This polypharmacy creates multiple interaction layers: sertraline inhibits CYP2D6 (affecting tramadol activation), additive serotonergic risk from sertraline + tramadol + trazodone, and additive CNS depression from trazodone + gabapentin + tramadol. The scenario demonstrates cascading interaction detection and risk stratification.', 'medications': ['sertraline', 'aripiprazole', 'trazodone', 'gabapentin', 'tramadol'], 'dose_events': [{'medication': 'sertraline', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 200.0, 'frequency': 'once daily'}, {'medication': 'aripiprazole', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 5.0, 'frequency': 'once daily'}, {'medication': 'trazodone', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 100.0, 'frequency': 'once daily at bedtime'}, {'medication': 'gabapentin', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 300.0, 'frequency': 'three times daily'}, {'medication': 'tramadol', 'event_type': 'steady_state', 'day': 0, 'dose_mg': 50.0, 'frequency': 'four times daily'}]}]
